/**
 * 负责四种已使用的有序请求绑定协议：接纳原请求、查询原作用域、比较期限别名并传播同一记录。
 * 输入为原请求和机制的晚读查询；输出为原 scope 引用或未接纳，绑定仅写本实例的运行 weak table。
 * 四个机制实例互不覆盖，可在同一请求上先后登记；每实例固定一个传播回调，顺序由装配端给出。
 * 原表没有期限数值检查、交付 guard、completion 或永久撤权；字段恢复可重新通过原查询，关闭仍由机制决定。
 * 只读 query 类型不冻结对象或授予权限；本 owner 不直接查询 World、Role、库存或档案，不新增授权判断。
 * 具体机制仍唯一拥有 scope、资源和关闭数据；这里仅保存原引用及请求关联。
 * 先写绑定再登记回调；后续 getter、比较或传播抛错保留已经完成的前缀，不回滚其它实例。
 */
import type { ActionRequest } from "./actions";
import { registerRequestAliasPropagation } from "./request_delivery";

/** 仅晚读原 scope 字段／活跃表；不接受整个请求回调，字段接纳与读取次序在本 owner 中实现。 */
export interface RequestLeaseScopeQueries<Owner, Scope> {
  active(owner: Owner): Scope | undefined;
  owner(scope: Scope): Owner;
  actorId(scope: Scope): number;
  phase(): ActionRequest["phase"];
  stage(scope: Scope): ActionRequest["context"]["stage"];
}

/** current 仍调用原机制规则；不能据请求字段相同代替原体、生命和库存复验。 */
export interface RequestLeaseCurrentQueries<Owner, Scope> extends RequestLeaseScopeQueries<Owner, Scope> {
  current(scope: Scope): boolean;
}

/** 墙入口先查原作者；原 token／实例值在条件和记录构造位置各自读取，不缓存授权或复制作者。 */
export interface RequestLeaseItemQueries<Owner, Scope, Author> {
  active(owner: Owner): Scope | undefined;
  authors(scope: Scope): Pick<ReadonlyMap<number, Author>, "get">;
  token(scope: Scope): string;
  instanceId(author: Author): string;
  phase(): ActionRequest["phase"];
  stage(): ActionRequest["context"]["stage"];
}

/** context 保原引用，记录不是请求 DTO；合法别名共享同一记录，不做深只读或序列化。 */
interface ScopeBinding<Scope> {
  scope: Scope;
  context: ActionRequest["context"];
}
interface CurrentBinding<Scope> {
  binding: Scope;
  context: ActionRequest["context"];
}
/** 捕获墙的原 owner／作者编号与实例值；后续查询仍晚查活跃墙，不能由编号自行生成许可。 */
interface ItemBinding<Owner, Scope> extends ScopeBinding<Scope> {
  world: Owner;
  actorId: number;
  instanceId: string;
}

// 排除 deadlineAtMs 是旧传播接受面，不代表期限有限、未过期或只会缩短。
function sameIndexedFields(source: ActionRequest, target: ActionRequest): boolean {
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  return !(
    keys.length !== other.length ||
    keys.some((k) => !other.includes(k) || (source as any)[k] !== (target as any)[k])
  );
}
function everyIndexedField(source: ActionRequest, target: ActionRequest): boolean {
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  return (
    keys.length === other.length &&
    keys.every((k) => other.includes(k) && (source as any)[k] === (target as any)[k])
  );
}
function everyReflectedField(source: ActionRequest, target: ActionRequest): boolean {
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  return (
    keys.length === other.length &&
    keys.every((k) => other.includes(k) && Reflect.get(source, k) === Reflect.get(target, k))
  );
}

/**
 * 每实例唯一持有请求登记；类型入口只开放固定协议，实际机制接线不传完整 request callback。
 * 私有构造签名限制 typed 调用，不是运行时权限屏障；接纳算法在本 owner 内完整执行。
 * 下列四个固定协议只组织当前已有读取顺序；不建立 Role 分派、注册表或通用规则框架。
 */
export class RequestLease<Owner, Scope, Binding> {
  private readonly records = new WeakMap<ActionRequest, Binding>();
  private readonly propagate = (source: ActionRequest, target: ActionRequest): void => {
    this.inherit(source, target);
  };

  private constructor(
    private readonly order: number,
    private readonly bindRequest: (owner: Owner, request: ActionRequest, lease: RequestLease<Owner, Scope, Binding>) => void,
    private readonly matches: (owner: Owner, request: ActionRequest, binding: Binding) => boolean,
    private readonly bindingOwner: (binding: Binding) => Owner,
    private readonly bindingScope: (binding: Binding) => Scope,
    private readonly sameFields: (source: ActionRequest, target: ActionRequest) => boolean,
  ) {}

  /** actor→phase→day→stage；查询还先核同一活跃 scope，不补机制的完整当前性判断。 */
  static actorPhaseDayStage<Owner, Scope>(
    queries: RequestLeaseScopeQueries<Owner, Scope>,
    order: number,
  ): RequestLease<Owner, Scope, ScopeBinding<Scope>> {
    return new RequestLease<Owner, Scope, ScopeBinding<Scope>>(
      order,
      (owner, request, lease) => {
        const scope = queries.active(owner);
        if (
          scope &&
          request.actorId === queries.actorId(scope) &&
          request.phase === queries.phase() &&
          request.context.day === 1 &&
          request.context.stage === queries.stage(scope)
        ) {
          lease.records.set(request, { scope, context: request.context });
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
        }
      },
      (owner, request, binding) =>
        queries.owner(binding.scope) === owner &&
        queries.active(owner) === binding.scope &&
        request.actorId === queries.actorId(binding.scope) &&
        request.context === binding.context &&
        request.phase === queries.phase() &&
        request.context.day === 1 &&
        request.context.stage === queries.stage(binding.scope),
      (binding) => queries.owner(binding.scope),
      (binding) => binding.scope,
      sameIndexedFields,
    );
  }

  /** stage→phase→day→actor→current；查询保原 context→stage→day→phase→current 顺序和 Reflect.get 比较。 */
  static stagePhaseDayActor<Owner, Scope>(
    queries: RequestLeaseCurrentQueries<Owner, Scope>,
    order: number,
  ): RequestLease<Owner, Scope, CurrentBinding<Scope>> {
    return new RequestLease<Owner, Scope, CurrentBinding<Scope>>(
      order,
      (owner, request, lease) => {
        const b = queries.active(owner);
        if (
          b &&
          request.context.stage === queries.stage(b) &&
          request.phase === queries.phase() &&
          request.context.day === 1 &&
          request.actorId === queries.actorId(b) &&
          queries.current(b)
        ) {
          lease.records.set(request, { binding: b, context: request.context });
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
        }
      },
      (owner, request, a) =>
        queries.owner(a.binding) === owner &&
        request.actorId === queries.actorId(a.binding) &&
        request.context === a.context &&
        request.context.stage === queries.stage(a.binding) &&
        request.context.day === 1 &&
        request.phase === queries.phase() &&
        queries.current(a.binding),
      (binding) => queries.owner(binding.binding),
      (binding) => binding.binding,
      everyReflectedField,
    );
  }

  /** actor→phase→stage→day→current；查询的 phase 必须先于 context 身份，不重排成上一种协议。 */
  static actorPhaseStageDay<Owner, Scope>(
    queries: RequestLeaseCurrentQueries<Owner, Scope>,
    order: number,
  ): RequestLease<Owner, Scope, CurrentBinding<Scope>> {
    return new RequestLease<Owner, Scope, CurrentBinding<Scope>>(
      order,
      (owner, request, lease) => {
        const b = queries.active(owner);
        if (
          b &&
          request.actorId === queries.actorId(b) &&
          request.phase === queries.phase() &&
          request.context.stage === queries.stage(b) &&
          request.context.day === 1 &&
          queries.current(b)
        ) {
          lease.records.set(request, { binding: b, context: request.context });
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
        }
      },
      (owner, request, a) =>
        queries.owner(a.binding) === owner &&
        request.actorId === queries.actorId(a.binding) &&
        request.phase === queries.phase() &&
        request.context === a.context &&
        request.context.stage === queries.stage(a.binding) &&
        request.context.day === 1 &&
        queries.current(a.binding),
      (binding) => queries.owner(binding.binding),
      (binding) => binding.binding,
      everyIndexedField,
    );
  }

  /** 原物品入口只核 token/instance；phase/day/stage 留在查询，不能提前强化接纳或原作者当前性。 */
  static item<Owner, Scope, Author>(
    queries: RequestLeaseItemQueries<Owner, Scope, Author>,
    order: number,
  ): RequestLease<Owner, Scope, ItemBinding<Owner, Scope>> {
    return new RequestLease<Owner, Scope, ItemBinding<Owner, Scope>>(
      order,
      (world, request, lease) => {
        const a = queries.active(world),
          author = a == null ? undefined : queries.authors(a).get(request.actorId);
        if (
          a &&
          author &&
          request.context.wall_id === queries.token(a) &&
          request.context.item_instance_id === queries.instanceId(author)
        ) {
          lease.records.set(request, {
            scope: a,
            world,
            actorId: request.actorId,
            instanceId: queries.instanceId(author),
            context: request.context,
          });
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
        }
      },
      (world, request, binding) =>
        queries.active(world) === binding.scope &&
        request.actorId === binding.actorId &&
        request.context === binding.context &&
        request.context.wall_id === queries.token(binding.scope) &&
        request.context.item_instance_id === binding.instanceId &&
        request.phase === queries.phase() &&
        request.context.day === 1 &&
        request.context.stage === queries.stage(),
      (binding) => binding.world,
      (binding) => binding.scope,
      sameIndexedFields,
    );
  }

  /** 各协议在原位置先取 set callee，再构造记录写表和登记；登记异常不撤销本次绑定。 */
  bind(owner: Owner, request: ActionRequest): void {
    this.bindRequest(owner, request, this);
  }

  /** 失配只拒本次查询；字段恢复仍按原机制规则核验，不自行关闭共同作用域。 */
  scope(owner: Owner, request: ActionRequest): Scope | undefined {
    const binding = this.records.get(request);
    return binding && this.matches(owner, request, binding) ? this.bindingScope(binding) : undefined;
  }

  /** 先查已登记来源和原 scope，再枚举 target；失败别名不修改来源，成功继承同一记录。 */
  private inherit(source: ActionRequest, target: ActionRequest): void {
    const binding = this.records.get(source);
    if (!binding || !this.scope(this.bindingOwner(binding), source)) return;
    if (!this.sameFields(source, target)) return;
    this.records.set(target, binding);
    registerRequestAliasPropagation(target, this.order, this.propagate);
  }
}

/**
 * 负责盗贼／千面人的初始选择 scope 与请求绑定。输入为原 World 参与者、首夜请求及装配端构造依赖；
 * 输出保留原选择结果与请求绑定；setup 仍当前时调用数据所有者写选择，再沿原物理换牌／身份安装顺序提交。
 * 工厂在原 scope 复验之后才 new，固定日次仍为 1；构造／请求异常保留已开准备前缀并由原 finally 关闭。
 * 失败选择与已关闭 setup 保留原终结决定；构造端口和元数据均不携带行动许可。
 * 请求记录及别名传播归独立公共实例；失配只拒本次查询，字段恢复仍按原规则检查，不新增期限校验。
 */
import { createCampComponent } from "../../../observation/component-presentation";
import type {
  ReadonlyBoardConfig,
} from "@ai-werewolf-arena/game-contract";
import { RequestLease } from "../../../../core/domain/request-lease";
import { copyEventData } from "@ai-werewolf-arena/game-contract";
import { COMPONENT, Camp, Phase, Role, createVictoryComponent, type ActionProvider, type ActionRequest, type CampComponent, type GameEvent, type RoleComponent, type VictoryComponent, type World } from "../../../../core/domain";
import { createRoleComponent } from "../../../observation/role-presentation";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import { ToolGateway } from "../../../gateway/tool_gateway";
import { getDefaultRoleCatalog } from "../role-catalog-assembly";
import {
  captureDebateParticipant,
  sameDebateParticipant,
  type DebateParticipant,
} from "../debater/authority";
import {
  openInitialIdentitySetup,
  closeInitialIdentitySetup,
  hasActiveInitialIdentitySetup,
  initialIdentityStock,
  initialIdentitySetupStatus,
  initialIdentitySetupReady,
  readInitialIdentityCard,
  pendingInitialIdentityDealValid,
  selectInitialIdentityCard,
  type InitialIdentityCard,
  type InitialIdentityDeal,
  type InitialIdentitySlot,
} from "./deal";
import { dataField } from "./data-ports";
import {
  getInitialIdentityState,
  readInitialIdentityTool,
  initialIdentityPolicy,
  initialIdentityRole,
  initialIdentityTool,
  initialIdentityChoiceRule,
  consumeRetainedInitialIdentityState,
  type InitialIdentityState,
} from "./choice";
import { initialIdentityKind, type InitialIdentityKind } from "./deal";
import { consumeShapeshifterState, cancelShapeshifterState } from "../shapeshifter/state-ports";
interface CardScope {
  card: InitialIdentityCard;
  cardId: string;
  role: Role;
}
export interface InitialIdentityScope {
  world: World;
  kind: InitialIdentityKind;
  actorId: number;
  deal: InitialIdentityDeal;
  reserve: InitialIdentityDeal["reserve"];
  hands: Map<number, InitialIdentityCard>;
  cards: readonly [CardScope, CardScope];
  originalHand: InitialIdentityCard;
  participants: readonly DebateParticipant[];
  actor: DebateParticipant;
  state: InitialIdentityState;
  camp: CampComponent;
  victory: VictoryComponent;
  victoryJson: string;
  config: ReadonlyBoardConfig;
  configJson: string;
  isCurrent: () => boolean;
  required: boolean;
  allowedSlots: readonly InitialIdentitySlot[];
}
const scopes = new WeakMap<World, InitialIdentityScope>();
/** 请求登记由独立公共实例持有；query 仍晚读原 scope，不替代完整选择许可。 */
const requestLease = RequestLease.actorPhaseDayStage<World, InitialIdentityScope>(
  {
    active: (world) => scopes.get(world),
    owner: (scope) => scope.world,
    actorId: (scope) => scope.actorId,
    phase: () => Phase.Night,
    stage: (scope) => scope.kind,
  },
  20,
);
function frozenJson(value: unknown): string | null {
  try {
    const copy = copyEventData(value);
    return copy === null ? null : JSON.stringify(copy);
  } catch {
    return null;
  }
}
function validCard(scope: CardScope): boolean {
  const card = readInitialIdentityCard(scope.card);
  return !!card && card.cardId === scope.cardId && card.role === scope.role;
}
export function sameInitialIdentityScope(scope: InitialIdentityScope): boolean {
  const { world, deal } = scope;
  const remaining = Object.getOwnPropertyDescriptor(scope.state, "remaining"),
    choice = Object.getOwnPropertyDescriptor(scope.state, "choice");
  const reserve0 = Object.getOwnPropertyDescriptor(scope.reserve, "0"),
    reserve1 = Object.getOwnPropertyDescriptor(scope.reserve, "1"),
    selection = Object.getOwnPropertyDescriptor(deal, "selection");
  return (
    scopes.get(world) === scope &&
    initialIdentityKind(world) === scope.kind &&
    hasActiveInitialIdentitySetup(world) &&
    initialIdentitySetupStatus(world) === "pending" &&
    scope.isCurrent() &&
    pendingInitialIdentityDealValid(world) &&
    initialIdentityStock(world) === deal &&
    dataField(deal, "hands") === scope.hands &&
    dataField(deal, "reserve") === scope.reserve &&
    scope.reserve.length === 2 &&
    [reserve0, reserve1].every((d) => d && Object.hasOwn(d, "value") && d.writable) &&
    reserve0!.value === scope.cards[0].card &&
    reserve1!.value === scope.cards[1].card &&
    scope.cards.every(validCard) &&
    scope.required ===
      initialIdentityChoiceRule(
        scope.kind,
        scope.cards.map((c) => c.role),
      ).mustChoose &&
    JSON.stringify(scope.allowedSlots) ===
      JSON.stringify(
        initialIdentityChoiceRule(
          scope.kind,
          scope.cards.map((c) => c.role),
        ).allowedSlots,
      ) &&
    Map.prototype.get.call(scope.hands, scope.actorId) === scope.originalHand &&
    scope.participants.length === world.entityIds().length &&
    scope.participants.every((p) => sameDebateParticipant(world, p)) &&
    getInitialIdentityState(scope.actor.role, scope.kind) === scope.state &&
    scope.state.policy === initialIdentityPolicy(scope.kind) &&
    remaining?.value === 1 &&
    remaining.writable === true &&
    choice?.value === null &&
    choice.writable === true &&
    world.getComponent(scope.actorId, COMPONENT.Camp) === scope.camp &&
    dataField(scope.camp, "camp") === Camp.Good &&
    world.getComponent(scope.actorId, COMPONENT.Victory) === scope.victory &&
    frozenJson(scope.victory) === scope.victoryJson &&
    frozenJson(scope.config) === scope.configJson &&
    selection?.value === null &&
    selection.writable === true
  );
}
export function authorizedInitialIdentityScope(
  world: World,
  actorId: number,
  day: number | undefined,
  phase: Phase,
  scope: object | undefined,
  kind: InitialIdentityKind,
): InitialIdentityScope | null {
  const active = scopes.get(world);
  return active &&
    active === scope &&
    active.kind === kind &&
    actorId === active.actorId &&
    day === 1 &&
    phase === Phase.Night &&
    sameInitialIdentityScope(active)
    ? active
    : null;
}
export function bindInitialIdentityRequest(world: World, request: ActionRequest): void {
  requestLease.bind(world, request);
}
export function initialIdentityRequestScope(
  world: World,
  request: ActionRequest,
): InitialIdentityScope | undefined {
  return requestLease.scope(world, request);
}
export function initialIdentityRequestChoices(
  world: World,
  actorId: number,
  kind: InitialIdentityKind,
) {
  const scope = scopes.get(world);
  if (
    !scope ||
    scope.kind !== kind ||
    scope.actorId !== actorId ||
    !sameInitialIdentityScope(scope)
  )
    return undefined;
  return {
    mustChoose: scope.required,
    allowedSlots: [...scope.allowedSlots],
    cards: scope.cards.map((card, slot) => ({
      slot: slot as InitialIdentitySlot,
      role: card.role,
    })),
  };
}
export class InitialIdentitySetupWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
    private readonly kind: InitialIdentityKind,
    /** 保存装配端对象；原创建点才读取构造器，不提前捕获类或共享已创建的工厂。 */
    private readonly construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
  ): Promise<boolean> {
    if (initialIdentityKind(this.world) !== this.kind) return true;
    if (hasActiveInitialIdentitySetup(this.world)) throw new Error(`${this.kind}_setup_reentry`);
    if (initialIdentitySetupReady(this.world)) return true;
    if (day !== 1 || initialIdentitySetupStatus(this.world) !== "pending" || !isCurrent())
      throw new Error(`${this.kind}_setup_unavailable`);
    const deal = openInitialIdentitySetup(this.world);
    let status: "complete" | "cancelled" | "failed" = "failed";
    try {
      if (!pendingInitialIdentityDealValid(this.world)) {
        status = "cancelled";
        return false;
      }
      const actorIds = this.world
        .getAliveEntityIds()
        .filter(
          (id) =>
            this.world.getComponent(id, COMPONENT.Role)?.role === initialIdentityRole(this.kind),
        );
      if (actorIds.length === 0) {
        status = "complete";
        return true;
      }
      if (actorIds.length !== 1) throw new Error(`${this.kind}_actor_invalid`);
      const actorId = actorIds[0]!,
        actor = captureDebateParticipant(this.world, actorId),
        state = getInitialIdentityState(actor?.role, this.kind),
        camp = this.world.getComponent(actorId, COMPONENT.Camp),
        victory = this.world.getComponent(actorId, COMPONENT.Victory);
      const cards = deal.reserve.map((card) => {
        const data = readInitialIdentityCard(card);
        return data ? { card, ...data } : null;
      });
      const configJson = frozenJson(config),
        victoryJson = frozenJson(victory);
      if (
        !actor ||
        actor.camp !== Camp.Good ||
        !state ||
        !camp ||
        !victory ||
        cards.some((card) => !card) ||
        configJson === null ||
        victoryJson === null
      ) {
        status = "cancelled";
        return false;
      }
      const participants = this.world
        .entityIds()
        .map((id) => captureDebateParticipant(this.world, id));
      if (participants.some((p) => !p)) {
        status = "cancelled";
        return false;
      }
      const scope: InitialIdentityScope = {
        world: this.world,
        kind: this.kind,
        actorId,
        deal,
        reserve: deal.reserve,
        hands: deal.hands,
        cards: cards as [CardScope, CardScope],
        originalHand: deal.hands.get(actorId)!,
        participants: participants as DebateParticipant[],
        actor,
        state,
        camp,
        victory,
        victoryJson,
        config,
        configJson,
        isCurrent,
        required: initialIdentityChoiceRule(
          this.kind,
          cards.map((c) => c!.role),
        ).mustChoose,
        allowedSlots: initialIdentityChoiceRule(
          this.kind,
          cards.map((c) => c!.role),
        ).allowedSlots,
      };
      scopes.set(this.world, scope);
      if (!sameInitialIdentityScope(scope)) {
        status = "cancelled";
        return false;
      }
      // 原 scope 已安装并复验后才读取构造器；构造或 create 失败仍走下方原 finally 关闭。
      const request = new this.construction.requestFactory(this.world, this.events, 1).create({
        phase: Phase.Night,
        actorId,
        allowedTools: [initialIdentityTool(this.kind)],
        stage: this.kind,
        requiresAction: scope.required,
        summary: {
          key:
            this.kind === "shapeshifter"
              ? "turn.shapeshifter.required"
              : scope.required
                ? "turn.thief.required"
                : "turn.thief.optional",
        },
        context: { allow_fallback: false, action_failure_policy: "error" },
      });
      if (!sameInitialIdentityScope(scope)) {
        status = "cancelled";
        return false;
      }
      const call = await provider.getAction(request);
      if (!sameInitialIdentityScope(scope)) {
        status = "cancelled";
        return false;
      }
      let slot: InitialIdentitySlot | null = null;
      if (call === null) {
        if (scope.required) throw new Error(`${this.kind}_required_choice_missing`);
      } else {
        const choiceCall = readInitialIdentityTool(call, this.kind);
        if (!choiceCall) throw new Error(`${this.kind}_choice_invalid`);
        const valid = this.gateway.validateAndSanitize(this.world, actorId, choiceCall, {
          phase: Phase.Night,
          day: 1,
          ...(this.kind === "thief" ? { thiefScope: scope } : { shapeshifterScope: scope }),
        });
        if (!sameInitialIdentityScope(scope)) {
          status = "cancelled";
          return false;
        }
        if (!valid.ok || !scope.allowedSlots.includes(choiceCall.args.slot))
          throw new Error(`${this.kind}_choice_invalid`);
        slot = choiceCall.args.slot;
      }
      const chosen = slot === null ? null : scope.cards[slot].card;
      const catalog = getDefaultRoleCatalog();
      const newRole = chosen
        ? createRoleComponent(chosen.role, catalog.getCamp(chosen.role), this.world.locale)
        : null;
      if (newRole)
        catalog.applyRuntime(newRole, {
          boardConfig: config,
          locale: this.world.locale,
          world: this.world,
        });
      const newCamp = newRole ? createCampComponent(newRole.camp, this.world.locale) : null;
      const newVictory = newRole
        ? createVictoryComponent([{ kind: "faction", faction: newRole.camp }])
        : null;
      if (!sameInitialIdentityScope(scope)) {
        status = "cancelled";
        return false;
      }
      // 物理交换与身份安装之间没有 await、Provider 回调或事件发表。
      if (chosen && slot !== null && newRole && newCamp && newVictory) {
        if (this.kind === "shapeshifter") {
          consumeShapeshifterState(state, slot);
        }
        selectInitialIdentityCard(this.world, actorId, slot);
        this.world.addComponent(actorId, COMPONENT.Role, newRole);
        this.world.addComponent(actorId, COMPONENT.Camp, newCamp);
        this.world.addComponent(actorId, COMPONENT.Victory, newVictory);
      } else {
        consumeRetainedInitialIdentityState(state);
        selectInitialIdentityCard(this.world, actorId, null);
      }
      status = "complete";
      closeInitialIdentitySetup(this.world, status);
      scopes.delete(this.world);
      const data = {
        actorId,
        day: 1 as const,
        role: newRole?.role ?? initialIdentityRole(this.kind),
        camp: newRole?.camp ?? Camp.Good,
      };
      this.events.push(
        this.kind === "shapeshifter"
          ? {
              timestamp: Date.now(),
              type: "shapeshifter_identity_chosen",
              payload: {
                ...data,
                slot: slot!,
                policy: "awa_netease_shapeshifter_two_extra_villagers_v1",
              },
            }
          : {
              timestamp: Date.now(),
              type: "thief_identity_chosen",
              payload: { ...data, slot, policy: "lui_meme_thief_two_extra_villagers_v1" },
            },
      );
      return true;
    } finally {
      if (this.kind === "shapeshifter" && status !== "complete") {
        const original =
          scopes.get(this.world)?.state ??
          this.world
            .entityIds()
            .map((id) =>
              getInitialIdentityState(this.world.getComponent(id, COMPONENT.Role), this.kind),
            )
            .find(Boolean);
        cancelShapeshifterState(original);
      }
      scopes.delete(this.world);
      closeInitialIdentitySetup(this.world, status);
    }
  }
}

/**
 * 负责野孩子参与者／榜样原生命、选择窗口、死亡提交与转阵营时序，拥有原 World 关系绑定。
 * 输入为原组件、首夜请求和实际死亡波；输出为原许可结果、阵营／Victory 及有界事实。
 * 不变量：仅在原身份／生命仍当前时提交；关闭、替换或截止别名仍按原政策撤权。
 * 槽所有者执行数据与 expectedState 写入；先发布榜样死亡事实再转换，失败不撤回已发表前缀。
 * 请求记录及别名传播归独立公共实例；请求字段失配只拒本次查询，原生命／准备撤权仍由本族决定。
 */
import { createCampComponent } from "../../../observation/component-presentation";
import type { WildChildReadState } from "@ai-werewolf-arena/game-contract";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { RequestLease } from "../../../../core/domain/request-lease";
import { COMPONENT, Camp, Role, Phase, createVictoryComponent, type World, type ActionRequest, type RoleComponent, type CampComponent, type VictoryComponent, type GameEvent, type DeathSources } from "../../../../core/domain";
import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import { captureDebateParticipant, type DebateParticipant } from "../debater/authority";
import { getWildChildState, encodeWildChildData as safeJson,
  commitWildChildState, cancelWildChildState, transformWildChildState, activateWildChildState,
  projectWildChildData } from "./state-slot";
export interface WildChildBinding {
  world: World;
  actorId: number;
  actor: DebateParticipant;
  state: WildChildReadState;
  config: ReadonlyBoardConfig;
  configJson: string;
  camp: CampComponent;
  victory: VictoryComponent;
  expectedState: string;
  victoryJson: string;
  model: NightLifeScope | null;
  setup: "pending" | "active" | "complete" | "failed" | "cancelled";
  actorDeath: boolean;
  modelDeath: boolean;
  modelCommitted: boolean;
}
const bindings = new WeakMap<World, WildChildBinding>();
const nights = new WeakMap<World, Set<number>>();
const activeNights = new WeakSet<World>();
/** 只传原绑定字段／当前性晚查询；请求、context 和别名记录由本实例唯一持有。 */
const requestLease = RequestLease.stagePhaseDayActor<World, WildChildBinding>(
  {
    active: (world) => bindings.get(world),
    owner: (binding) => binding.world,
    actorId: (binding) => binding.actorId,
    phase: () => Phase.Night,
    stage: () => "wild_child",
    current: (binding) => validWildChildChoice(binding),
  },
  30,
);
const windows = new WeakMap<
  World,
  { isCurrent: () => boolean; targets: Map<number, DebateParticipant> }
>();

export function installWildChild(world: World, config: ReadonlyBoardConfig): void {
  if (bindings.has(world)) throw new Error("wild_child_already_installed");
  const actorId = world
    .entityIds()
    .find((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.WildChild);
  if (actorId === undefined) return;
  const actor = captureDebateParticipant(world, actorId)!;
  const state = getWildChildState(actor.role)!;
  const camp = world.getComponent(actorId, COMPONENT.Camp)!;
  const victory = world.getComponent(actorId, COMPONENT.Victory)!;
  bindings.set(world, {
    world,
    actorId,
    actor,
    state,
    config,
    configJson: safeJson(config),
    camp,
    victory,
    expectedState: safeJson(state),
    victoryJson: safeJson(victory),
    model: null,
    setup: "pending",
    actorDeath: false,
    modelDeath: false,
    modelCommitted: false,
  });
}
export function wildChildBinding(world: World): WildChildBinding | undefined {
  return bindings.get(world);
}
function ownData(value: object, key: string): unknown {
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && Object.hasOwn(d, "value") ? d.value : undefined;
}
function captureChoiceTarget(world: World, id: number): DebateParticipant | null {
  const life = captureNightLife(world, id),
    role = world.getComponent(id, COMPONENT.Role);
  if (!life || !role) return null;
  const roleId = ownData(role, "role"),
    camp = ownData(role, "camp"),
    state = ownData(role, "privateState");
  if (typeof roleId !== "string" || typeof camp !== "string" || !state || typeof state !== "object")
    return null;
  return {
    life,
    role,
    roleId: roleId as RoleComponent["role"],
    camp: camp as RoleComponent["camp"],
    state: state as RoleComponent["privateState"],
  };
}
function sameChoiceTarget(world: World, snapshot: DebateParticipant): boolean {
  return (
    livingNightLife(world, snapshot.life) &&
    world.getComponent(snapshot.life.id, COMPONENT.Role) === snapshot.role &&
    ownData(snapshot.role, "role") === snapshot.roleId &&
    ownData(snapshot.role, "camp") === snapshot.camp &&
    ownData(snapshot.role, "privateState") === snapshot.state
  );
}
function validWildChildIdentity(b: WildChildBinding): boolean {
  return (
    bindings.get(b.world) === b &&
    b.world.getComponent(b.actorId, COMPONENT.Role) === b.actor.role &&
    ownData(b.actor.role, "role") === Role.WildChild &&
    ownData(b.actor.role, "camp") === b.actor.camp &&
    ownData(b.actor.role, "privateState") === b.actor.state &&
    ownData(b.actor.state, "wildChild") === b.state &&
    safeJson(b.state) !== "invalid" &&
    safeJson(b.state) === b.expectedState &&
    b.world.getComponent(b.actorId, COMPONENT.Camp) === b.camp &&
    ownData(b.camp, "camp") === b.actor.camp &&
    b.world.getComponent(b.actorId, COMPONENT.Victory) === b.victory &&
    safeJson(b.victory) !== "invalid" &&
    safeJson(b.victory) === b.victoryJson &&
    safeJson(b.config) !== "invalid" &&
    safeJson(b.config) === b.configJson
  );
}
export function validWildChildOwner(b: WildChildBinding): boolean {
  return validWildChildIdentity(b) && livingNightLife(b.world, b.actor.life);
}
export function projectWildChild(
  world: World,
  role: RoleComponent,
): WildChildReadState | undefined {
  const b = bindings.get(world);
  if (!b || b.actor.role !== role) return undefined;
  return projectWildChildData(b, () => validWildChildOwner(b));
}
export function wildChildReady(world: World): boolean {
  const b = bindings.get(world);
  return !b || b.setup === "complete";
}
export function hasActiveWildChild(world: World): boolean {
  return bindings.get(world)?.setup === "active" || activeNights.has(world);
}
export function hasWildChildNightCommit(world: World, day: number): boolean {
  return nights.get(world)?.has(day) ?? false;
}
export function openWildChildChoice(b: WildChildBinding, isCurrent: () => boolean): void {
  if (b.setup !== "pending" || !validWildChildOwner(b))
    throw new Error("wild_child_setup_unavailable");
  b.setup = "active";
  windows.set(b.world, {
    isCurrent,
    targets: new Map(
      b.world
        .getAliveEntityIds()
        .filter((id) => id !== b.actorId)
        .map((id) => [id, captureChoiceTarget(b.world, id)!]),
    ),
  });
}
export function validWildChildChoice(b: WildChildBinding): boolean {
  const w = windows.get(b.world);
  return (
    !!w &&
    w.isCurrent() &&
    b.setup === "active" &&
    validWildChildOwner(b) &&
    b.state.status === "pending" &&
    b.state.remaining === 1 &&
    b.state.choice === null &&
    [...w.targets.values()].every((p) => !!p && sameChoiceTarget(b.world, p))
  );
}
export function authorizedWildChild(
  world: World,
  actorId: number,
  day: number | undefined,
  phase: Phase,
  scope: object | undefined,
): boolean {
  const b = bindings.get(world);
  return (
    !!b &&
    b === scope &&
    actorId === b.actorId &&
    day === 1 &&
    phase === Phase.Night &&
    validWildChildChoice(b)
  );
}
export function bindWildChildRequest(world: World, request: ActionRequest): void {
  requestLease.bind(world, request);
}
export function wildChildRequestScope(
  world: World,
  request: ActionRequest,
): WildChildBinding | undefined {
  return requestLease.scope(world, request);
}
export function commitWildChildChoice(b: WildChildBinding, targetId: number): boolean {
  const target = windows.get(b.world)?.targets.get(targetId);
  if (!validWildChildChoice(b) || !target || !sameChoiceTarget(b.world, target)) return false;
  const choice = { day: 1 as const, targetId };
  if (!commitWildChildState(b, choice, () => target.life)) return false;
  b.setup = "complete";
  windows.delete(b.world);
  return true;
}
export function closeWildChildChoice(b: WildChildBinding, status: "failed" | "cancelled"): void {
  if (b.setup === "complete") return;
  b.setup = status;
  windows.delete(b.world);
  cancelWildChildState(b);
}
/** 紧邻实际引擎 Alive 提交之前调用，不由查询或原始拟议目标调用。 */
export function recordWildChildDeathCommit(world: World, id: number): void {
  const b = bindings.get(world);
  if (!b || !validWildChildIdentity(b)) return;
  if (id === b.actorId && livingNightLife(world, b.actor.life)) b.actorDeath = true;
  if (
    b.setup === "complete" &&
    !b.modelCommitted &&
    b.state.status === "chosen" &&
    b.model?.id === id &&
    livingNightLife(world, b.model)
  )
    b.modelDeath = true;
}
/** 调用前标记完整 pending 死亡波；后续射击波独立提交。 */
export function resolveWildChildDeathWave(
  world: World,
  ids: readonly number[],
  sources: DeathSources,
  day: number,
  phase: Phase,
  events: GameEvent[],
): void {
  const b = bindings.get(world),
    model = b?.model;
  if (
    !b ||
    !model ||
    !b.modelDeath ||
    b.modelCommitted ||
    !ids.includes(model.id) ||
    world.getComponent(model.id, COMPONENT.Alive) !== model.life ||
    model.life.alive ||
    aliveLifeVersion(model.life) !== model.version + 1
  )
    return;
  b.modelCommitted = true;
  const deathCommit = `wild-model:${b.actorId}:${model.id}:${day}`;
  events.push({
    timestamp: Date.now(),
    type: "wild_child_model_eliminated",
    payload: {
      actorId: b.actorId,
      targetId: model.id,
      day,
      phase,
      deathCommit,
      sources: [...(sources[model.id] ?? [])],
      deadIds: [...ids],
    },
  });
  if (
    !validWildChildOwner(b) ||
    b.state.status !== "chosen" ||
    b.actor.camp !== Camp.Good ||
    !["status", "eligibleNight"].every(
      (k) => Object.getOwnPropertyDescriptor(b.state, k)?.writable,
    ) ||
    !Object.getOwnPropertyDescriptor(b.actor.role, "camp")?.writable
  )
    return;
  const camp = createCampComponent(Camp.Wolf, world.locale),
    victory = createVictoryComponent([{ kind: "faction", faction: Camp.Wolf }]);
  b.actor.role.camp = Camp.Wolf;
  world.addComponent(b.actorId, COMPONENT.Camp, camp);
  world.addComponent(b.actorId, COMPONENT.Victory, victory);
  b.actor.camp = Camp.Wolf;
  b.camp = camp;
  b.victory = victory;
  b.victoryJson = safeJson(victory);
  transformWildChildState(b, day);
  events.push({
    timestamp: Date.now(),
    type: "wild_child_transformed",
    payload: { actorId: b.actorId, day, eligibleNight: day + 1, camp: Camp.Wolf, deathCommit },
  });
}
export function wildChildPackKnown(role: RoleComponent, world?: World): boolean {
  const b = world && bindings.get(world);
  if (
    !b ||
    b.actor.role !== role ||
    !validWildChildIdentity(b) ||
    b.setup !== "complete" ||
    b.state.status !== "active"
  )
    return false;
  return (
    livingNightLife(b.world, b.actor.life) ||
    (b.actorDeath &&
      b.world.getComponent(b.actorId, COMPONENT.Alive) === b.actor.life.life &&
      !b.actor.life.life.alive &&
      aliveLifeVersion(b.actor.life.life) === b.actor.life.version + 1)
  );
}
export function wildChildPackActive(role: RoleComponent, world?: World): boolean {
  const b = world && bindings.get(world);
  return !!b && wildChildPackKnown(role, world) && validWildChildOwner(b);
}
export function openWildChildNight(world: World, day: number, events: GameEvent[]): () => void {
  const b = bindings.get(world);
  if (!b) return () => {};
  if (hasActiveWildChild(world) || hasWildChildNightCommit(world, day) || !wildChildReady(world))
    throw new Error("wild_child_night_unavailable");
  const days = nights.get(world) ?? new Set<number>();
  days.add(day);
  nights.set(world, days);
  activeNights.add(world);
  try {
    if (
      validWildChildOwner(b) &&
      b.state.status === "transformed" &&
      b.state.eligibleNight !== null &&
      day >= b.state.eligibleNight &&
      ["status", "activeFromNight"].every(
        (k) => Object.getOwnPropertyDescriptor(b.state, k)?.writable,
      )
    ) {
      activateWildChildState(b, day);
      events.push({
        timestamp: Date.now(),
        type: "wild_child_pack_activated",
        payload: { actorId: b.actorId, day, eligibleNight: b.state.eligibleNight },
      });
    }
  } catch (error) {
    activeNights.delete(world);
    throw error;
  }
  return () => {
    activeNights.delete(world);
  };
}

/**
 * 负责野孩子首夜榜样选择窗口，保留原参与者、只读板子和 provider；请求工厂由装配端晚提供。
 * 输入为已安装绑定、首夜日期及当前性回调；输出为榜样提交成功或准备中断。
 * 先核准备状态再开选择，await 两侧复验原生命和目标；选择、付款与失败关闭归原生命周期。
 * 窗口不修改板子参数、不重新发库存，也不把过期请求当成选择许可。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { Phase, type World, type GameEvent, type ActionProvider } from "../../../../core/domain";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import { readWildChildTool } from "./state-slot";
import {
  wildChildBinding,
  wildChildReady,
  openWildChildChoice,
  validWildChildChoice,
  commitWildChildChoice,
  closeWildChildChoice,
  hasActiveWildChild,
} from "./lifecycle";
export class WildChildSetupWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
    /** 只保存惰性构造依赖；不预建请求，原准备和权限检查仍先执行。 */
    private readonly construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
  ): Promise<boolean> {
    if (hasActiveWildChild(this.world)) throw new Error("wild_child_setup_reentry");
    if (wildChildReady(this.world)) return true;
    const b = wildChildBinding(this.world);
    if (!b || config !== b.config || day !== 1 || !isCurrent())
      throw new Error("wild_child_setup_unavailable");
    let status: "failed" | "cancelled" = "failed";
    try {
      openWildChildChoice(b, isCurrent);
      // 原选择窗口已开后才取构造器，并用本次 World／事件／day 创建实例；失败仍按原 finally 关闭。
      const request = new this.construction.requestFactory(this.world, this.events, day).create({
        phase: Phase.Night,
        actorId: b.actorId,
        allowedTools: ["choose_wild_model"],
        stage: "wild_child",
        requiresAction: true,
        summary: { key: "turn.wild_child.required" },
        context: { allow_fallback: false, action_failure_policy: "error" },
      });
      if (!validWildChildChoice(b)) {
        status = "cancelled";
        return false;
      }
      const raw = await provider.getAction(request);
      if (!validWildChildChoice(b)) {
        status = "cancelled";
        return false;
      }
      const call = readWildChildTool(raw);
      if (!call) throw new Error("wild_child_required_choice_missing");
      const result = this.gateway.validateAndSanitize(this.world, b.actorId, call, {
        phase: Phase.Night,
        day,
        wildChildScope: b,
      });
      if (!validWildChildChoice(b)) {
        status = "cancelled";
        return false;
      }
      if (!result.ok || !commitWildChildChoice(b, call.args.target_id))
        throw new Error("wild_child_choice_invalid");
      this.events.push({
        timestamp: Date.now(),
        type: "wild_child_model_chosen",
        payload: { actorId: b.actorId, day: 1, targetId: call.args.target_id },
      });
      return true;
    } finally {
      closeWildChildChoice(b, status);
    }
  }
}

/**
 * 负责孤独少女首夜选择、原参与者／生命与独立 Victory 归属，拥有原关系绑定及窗口时序。
 * 输入为原 World 参与者和首夜请求；输出为已接受选择、捕获目标阵营对应的成员关系及原准备结果。
 * 不变量：仅在原身份／资源仍匹配时提交；关闭或替换参与者使 scope 失效，包括期限别名。
 * 选择不改变演员的 Role／Camp，已选成员关系在双方死亡后仍保留；本模块不新增目标死亡结算。
 * 数据写由槽执行，失败窗口审计保留原授权身份，不读取外来 accessor 或恢复已消耗库存。
 * 请求记录及别名传播归独立公共实例；请求字段失配只拒本次查询，原生命／准备撤权仍由本族决定。
 */
import type { LonelyGirlReadState } from "@ai-werewolf-arena/game-contract";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { RequestLease } from "../../../../core/domain/request-lease";
import { copyEventData } from "@ai-werewolf-arena/game-contract";
import {
  COMPONENT,
  Camp,
  Role,
  Phase,
  createVictoryComponent,
  type World,
  type ActionRequest,
  type RoleComponent,
  type CampComponent,
  type VictoryComponent,
} from "../../../../core/domain";
import { aliveLifeVersion, type AliveComponent } from "../../../../core/domain/components/alive";
import { freshLonelyGirlState, getLonelyGirlState, LONELY_GIRL_POLICY, lonelyData,
  consumeLonelyGirlState, cancelLonelyGirlState, projectLonelyGirlData } from "./state-slot";
interface Participant {
  id: number;
  life: AliveComponent;
  version: number;
  alive: PropertyDescriptor;
  role: RoleComponent;
  kind: Role;
  roleCamp: Camp;
  state: RoleComponent["privateState"];
  camp: CampComponent;
  campValue: Camp;
  privateSnapshot: Record<string, unknown>;
}
export interface LonelyGirlBinding {
  world: World;
  actorId: number;
  actor: Participant;
  participants: ReadonlyMap<number, Participant>;
  state: LonelyGirlReadState;
  config: ReadonlyBoardConfig;
  configJson: string;
  victory: VictoryComponent;
  affiliations: VictoryComponent["affiliations"];
  status: "pending" | "active" | "complete" | "failed" | "cancelled";
  choice: LonelyGirlReadState["choice"];
  membership: Camp | null;
  isCurrent: (() => boolean) | null;
}
const bindings = new WeakMap<World, LonelyGirlBinding>(),
  nights = new WeakMap<World, Set<number>>(),
  activeNights = new WeakSet<World>();
/** phase 先于 context 身份的原协议独立保留；不复制选择许可或引入请求永久撤权。 */
const requestLease = RequestLease.actorPhaseStageDay<World, LonelyGirlBinding>(
  {
    active: (world) => bindings.get(world),
    owner: (binding) => binding.world,
    actorId: (binding) => binding.actorId,
    phase: () => Phase.Night,
    stage: () => "lonely_girl",
    current: (binding) => validLonelyGirlChoice(binding),
  },
  40,
);
function safeJson(value: unknown): string | null {
  try {
    const p = copyEventData(value);
    return p === null ? null : JSON.stringify(p);
  } catch {
    return null;
  }
}
function capture(world: World, id: number): Participant | null {
  const life = world.getComponent(id, COMPONENT.Alive),
    role = world.getComponent(id, COMPONENT.Role),
    camp = world.getComponent(id, COMPONENT.Camp),
    version = life && aliveLifeVersion(life),
    alive = life && Object.getOwnPropertyDescriptor(life, "alive"),
    kind = lonelyData(role, "role"),
    roleCamp = lonelyData(role, "camp"),
    state = lonelyData(role, "privateState"),
    campValue = lonelyData(camp, "camp");
  if (
    !life ||
    version === undefined ||
    !alive ||
    life.alive !== true ||
    !role ||
    !camp ||
    typeof kind !== "string" ||
    !state ||
    typeof state !== "object" ||
    ![Camp.Good, Camp.Wolf].includes(roleCamp as Camp) ||
    campValue !== roleCamp
  )
    return null;
  return {
    id,
    life,
    version,
    alive,
    role,
    kind: kind as Role,
    roleCamp: roleCamp as Camp,
    state: state as RoleComponent["privateState"],
    camp,
    campValue: campValue as Camp,
    privateSnapshot: structuredClone(state) as Record<string, unknown>,
  };
}
function same(world: World, p: Participant): boolean {
  const d = Object.getOwnPropertyDescriptor(p.life, "alive");
  return (
    world.getComponent(p.id, COMPONENT.Alive) === p.life &&
    aliveLifeVersion(p.life) === p.version &&
    !!d &&
    d.get === p.alive.get &&
    d.set === p.alive.set &&
    d.value === p.alive.value &&
    p.life.alive === true &&
    world.getComponent(p.id, COMPONENT.Role) === p.role &&
    lonelyData(p.role, "role") === p.kind &&
    lonelyData(p.role, "camp") === p.roleCamp &&
    lonelyData(p.role, "privateState") === p.state &&
    world.getComponent(p.id, COMPONENT.Camp) === p.camp &&
    lonelyData(p.camp, "camp") === p.campValue
  );
}
export function installLonelyGirl(world: World, config: ReadonlyBoardConfig): void {
  if (bindings.has(world)) throw new Error("lonely_girl_already_installed");
  const actorId = world
    .entityIds()
    .find((id) => lonelyData(world.getComponent(id, COMPONENT.Role), "role") === Role.LonelyGirl);
  if (actorId === undefined) return;
  const participants = new Map(world.entityIds().map((id) => [id, capture(world, id)] as const)),
    actor = participants.get(actorId),
    state = getLonelyGirlState(actor?.role),
    victory = world.getComponent(actorId, COMPONENT.Victory),
    affiliations = lonelyData(victory, "affiliations"),
    configJson = safeJson(config);
  if (
    !actor ||
    !state ||
    !victory ||
    !Array.isArray(affiliations) ||
    safeJson(affiliations) !== "[]" ||
    !configJson ||
    [...participants.values()].some((p) => !p)
  )
    throw new Error("lonely_girl_initial_state_invalid");
  bindings.set(world, {
    world,
    actorId,
    actor,
    participants: participants as Map<number, Participant>,
    state,
    config,
    configJson,
    victory,
    affiliations,
    status: "pending",
    choice: null,
    membership: null,
    isCurrent: null,
  });
}
export function lonelyGirlBinding(world: World): LonelyGirlBinding | undefined {
  return bindings.get(world);
}
function pendingOwner(b: LonelyGirlBinding): boolean {
  const rem = Object.getOwnPropertyDescriptor(b.state, "remaining"),
    choice = Object.getOwnPropertyDescriptor(b.state, "choice");
  return (
    bindings.get(b.world) === b &&
    b.participants.size === b.world.entityIds().length &&
    [...b.participants.values()].every((p) => same(b.world, p)) &&
    b.actor.kind === Role.LonelyGirl &&
    b.actor.roleCamp === Camp.Good &&
    getLonelyGirlState(b.actor.role) === b.state &&
    rem?.value === 1 &&
    rem.writable === true &&
    choice?.value === null &&
    choice.writable === true &&
    b.world.getComponent(b.actorId, COMPONENT.Victory) === b.victory &&
    lonelyData(b.victory, "affiliations") === b.affiliations &&
    safeJson(b.affiliations) === "[]" &&
    safeJson(b.config) === b.configJson
  );
}
export function lonelyGirlReady(world: World): boolean {
  const b = bindings.get(world);
  return b
    ? b.status === "complete"
    : !world
        .entityIds()
        .some(
          (id) => lonelyData(world.getComponent(id, COMPONENT.Role), "role") === Role.LonelyGirl,
        );
}
export function hasActiveLonelyGirl(world: World): boolean {
  return bindings.get(world)?.status === "active" || activeNights.has(world);
}
export function hasLonelyGirlNightCommit(world: World, day: number): boolean {
  return nights.get(world)?.has(day) ?? false;
}
export function openLonelyGirlChoice(b: LonelyGirlBinding, isCurrent: () => boolean): boolean {
  if (b.status !== "pending") throw new Error("lonely_girl_setup_unavailable");
  b.status = "active";
  b.isCurrent = isCurrent;
  return validLonelyGirlChoice(b);
}
export function validLonelyGirlChoice(b: LonelyGirlBinding): boolean {
  return b.status === "active" && b.isCurrent?.() === true && pendingOwner(b);
}
export function authorizedLonelyGirl(
  world: World,
  actorId: number,
  day: number | undefined,
  phase: Phase,
  scope: object | undefined,
): boolean {
  const b = bindings.get(world);
  return (
    !!b &&
    b === scope &&
    b.actorId === actorId &&
    day === 1 &&
    phase === Phase.Night &&
    validLonelyGirlChoice(b)
  );
}
export function bindLonelyGirlRequest(world: World, request: ActionRequest): void {
  requestLease.bind(world, request);
}
export function lonelyGirlRequestScope(
  world: World,
  request: ActionRequest,
): LonelyGirlBinding | undefined {
  return requestLease.scope(world, request);
}
export function commitLonelyGirlChoice(b: LonelyGirlBinding, targetId: number): Camp | null {
  const target = b.participants.get(targetId);
  if (!target || targetId === b.actorId || !validLonelyGirlChoice(b)) return null;
  const choice = { day: 1 as const, targetId },
    membership = createVictoryComponent([{ kind: "faction", faction: target.campValue }]);
  // 最后权限检查后依次交数据所有者写库存与选择，再安装 Victory；两者之间没有 await。
  consumeLonelyGirlState(b, choice);
  b.world.addComponent(b.actorId, COMPONENT.Victory, membership);
  b.choice = Object.freeze({ ...choice });
  b.membership = target.campValue;
  b.status = "complete";
  b.isCurrent = null;
  return target.campValue;
}
export function closeLonelyGirlChoice(b: LonelyGirlBinding, status: "failed" | "cancelled"): void {
  if (b.status === "complete") return;
  b.status = status;
  b.isCurrent = null;
  cancelLonelyGirlState(b);
}
export function projectLonelyGirl(
  world: World,
  role: RoleComponent,
): LonelyGirlReadState | undefined {
  const b = bindings.get(world);
  if (!b || b.actor.role !== role) return undefined;
  return projectLonelyGirlData(b, () => pendingOwner(b));
}
export function projectLonelyGirlSetup(world: World) {
  const b = bindings.get(world);
  return b
    ? {
        policy: LONELY_GIRL_POLICY,
        status: b.status === "active" ? ("pending" as const) : b.status,
        actorId: b.actorId,
      }
    : undefined;
}
export function projectLonelyGirlVictory(
  world: World,
  actorId: number,
): VictoryComponent | undefined {
  const b = bindings.get(world);
  return b?.actorId === actorId
    ? createVictoryComponent(b.membership ? [{ kind: "faction", faction: b.membership }] : [])
    : undefined;
}
export function openLonelyGirlNight(world: World, day: number): () => void {
  if (!bindings.has(world)) return () => {};
  if (hasActiveLonelyGirl(world) || !lonelyGirlReady(world) || hasLonelyGirlNightCommit(world, day))
    throw new Error("lonely_girl_night_unavailable");
  const days = nights.get(world) ?? new Set<number>();
  days.add(day);
  nights.set(world, days);
  activeNights.add(world);
  return () => {
    activeNights.delete(world);
  };
}

/** 失败窗口审计使用原授权身份／资源，不读取 foreign accessor。 */
export function projectLonelyGirlAuditPlayer(world: World, id: number) {
  const b = bindings.get(world),
    p = b?.participants.get(id);
  if (!b || !p || (b.status !== "failed" && b.status !== "cancelled")) return undefined;
  const alive = p.alive.get ? p.alive.get.call(p.life) === true : p.alive.value === true;
  return {
    role: p.kind,
    camp: p.roleCamp,
    alive,
    privateState:
      id === b.actorId
        ? { lonelyGirl: { ...freshLonelyGirlState(), remaining: 0 } }
        : structuredClone(p.privateSnapshot),
  };
}

/**
 * 负责孤独少女首夜心仪对象选择及原失败／取消路径。
 * 输入为只读板子、原参与者、provider 和惰性构造依赖；输出为心仪对象提交成功或准备中断。
 * 先核准备状态再打开原窗口，await 两侧复验参与者；阵营归属、库存及 finally 关闭归原生命周期。
 * 已失败或关闭的选择不重写游戏参数，不重新开启准备，也不授予过期请求许可。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { Phase, type World, type GameEvent, type ActionProvider } from "../../../../core/domain";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import { LONELY_GIRL_POLICY, readLonelyGirlTool } from "./state-slot";
import {
  lonelyGirlBinding,
  lonelyGirlReady,
  hasActiveLonelyGirl,
  openLonelyGirlChoice,
  validLonelyGirlChoice,
  commitLonelyGirlChoice,
  closeLonelyGirlChoice,
} from "./lifecycle";
export class LonelyGirlSetupWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
    /** 只保存惰性构造依赖；不预建请求，原准备和权限检查仍先执行。 */
    private readonly construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
  ): Promise<boolean> {
    if (hasActiveLonelyGirl(this.world)) throw new Error("lonely_girl_setup_reentry");
    if (lonelyGirlReady(this.world)) return true;
    const b = lonelyGirlBinding(this.world);
    if (!b || b.status !== "pending" || config !== b.config || day !== 1)
      throw new Error("lonely_girl_setup_unavailable");
    let status: "failed" | "cancelled" = "failed";
    try {
      if (!openLonelyGirlChoice(b, isCurrent)) {
        status = "cancelled";
        return false;
      }
      // 原选择窗口已开后才取构造器，并用本次 World／事件／day 创建实例；失败仍按原 finally 关闭。
      const request = new this.construction.requestFactory(this.world, this.events, day).create({
        phase: Phase.Night,
        actorId: b.actorId,
        allowedTools: ["choose_admired_player"],
        stage: "lonely_girl",
        requiresAction: true,
        summary: { key: "turn.lonely_girl.required" },
        context: { allow_fallback: false, action_failure_policy: "error" },
      });
      if (!validLonelyGirlChoice(b)) {
        status = "cancelled";
        return false;
      }
      const raw = await provider.getAction(request);
      if (!validLonelyGirlChoice(b)) {
        status = "cancelled";
        return false;
      }
      const call = readLonelyGirlTool(raw);
      if (!call) throw new Error("lonely_girl_required_choice_missing");
      const result = this.gateway.validateAndSanitize(this.world, b.actorId, call, {
        phase: Phase.Night,
        day,
        lonelyGirlScope: b,
      });
      if (!validLonelyGirlChoice(b)) {
        status = "cancelled";
        return false;
      }
      if (!result.ok) throw new Error("lonely_girl_choice_invalid");
      const camp = commitLonelyGirlChoice(b, call.args.target_id);
      if (!camp) throw new Error("lonely_girl_choice_invalid");
      this.events.push({
        timestamp: Date.now(),
        type: "lonely_girl_admired_chosen",
        payload: {
          policy: LONELY_GIRL_POLICY,
          actorId: b.actorId,
          day: 1,
          targetId: call.args.target_id,
          camp,
        },
      });
      return true;
    } finally {
      closeLonelyGirlChoice(b, status);
    }
  }
}

/**
 * 负责拥有当前匿名墙、原作者库存与请求绑定，按窗口和作者身份提交行动及派生别名。
 * 输入为原 World、作者与请求；输出为已接受墙操作，写权只覆盖该作者／窗口的库存及绑定。
 * 不变量：别名必须保留原请求身份和窗口校验。关闭墙或参与者替换撤销本地权限，
 * 失败仍保留原已提交前缀，不以别名跳过 authority 检查。
 * 请求记录及别名传播归独立公共实例；不新增期限检查或永久撤权，原作者与活跃墙仍按原条件查询。
 */
import { RequestLease } from "../../../../core/domain/request-lease";
import { readWallNoteData } from "@ai-werewolf-arena/game-contract/facts/wall-notes";
import {
  COMPONENT,
  Role,
  Phase,
  type World,
  type ActionRequest,
  type WallNoteComponent,
} from "../../../../core/domain";
import {
  captureDebateParticipant,
  sameDebateParticipant,
  type DebateParticipant,
} from "../../roles/debater/authority";
export const WALL_ROLES: readonly Role[] = [
  Role.Wolf,
  Role.Villager,
  Role.Seer,
  Role.Witch,
  Role.Hunter,
  Role.Guard,
  Role.Idiot,
];
export function supportsWallRoles(roles: readonly Role[]): boolean {
  return roles.every((role) => WALL_ROLES.includes(role));
}
export interface WallAuthor {
  id: number;
  participant: DebateParticipant;
  note: WallNoteComponent;
  source: WallNoteComponent["source"];
  instanceId: string;
  remaining: 0 | 1;
  closed: boolean;
}
export interface WallAuthority {
  token: string;
  authors: Map<number, WallAuthor>;
  isCurrent: () => boolean;
}
const active = new WeakMap<World, WallAuthority>();
const commits = new WeakSet<World>();
const owned = new WeakMap<World, Map<number, WallAuthor>>();
/** 本实例只登记请求；原 active/author/库存表仍归本 authority，入口不提前核阶段或当前作者。 */
const requestLease = RequestLease.item<World, WallAuthority, WallAuthor>(
  {
    active: (world) => active.get(world),
    authors: (scope) => scope.authors,
    token: (scope) => scope.token,
    instanceId: (author) => author.instanceId,
    phase: () => Phase.Voting,
    stage: () => "wall_notes",
  },
  10,
);
export function bindWallRequest(world: World, request: ActionRequest): void {
  requestLease.bind(world, request);
}
export function wallRequestScope(world: World, request: ActionRequest): WallAuthority | undefined {
  return requestLease.scope(world, request);
}
export function hasActiveWall(world: World): boolean {
  return active.has(world);
}
export function hasWallCommit(world: World): boolean {
  return commits.has(world);
}
export function openWall(world: World, isCurrent: () => boolean): WallAuthority {
  if (hasActiveWall(world)) throw new Error("wall_window_reentry");
  if (hasWallCommit(world)) throw new Error("wall_already_committed");
  commits.add(world);
  const a: WallAuthority = { token: "wall:1", authors: new Map(), isCurrent };
  active.set(world, a);
  return a;
}
export function grantWallNote(world: World, a: WallAuthority, id: number): WallAuthor | null {
  const participant = captureDebateParticipant(world, id);
  if (!participant) return null;
  const source: WallNoteComponent["source"] = {
    kind: "wall_event",
    eventId: "awa_wall_notes_v1",
    day: 1,
  };
  const note: WallNoteComponent = {
    instanceId: `wall:1:${id}`,
    source,
    remaining: 1,
    expired: false,
  };
  const author: WallAuthor = {
    id,
    participant,
    note,
    source,
    instanceId: note.instanceId,
    remaining: 1,
    closed: false,
  };
  world.addComponent(id, COMPONENT.WallNote, note);
  a.authors.set(id, author);
  owned.set(world, a.authors);
  return author;
}
export function sameWallAuthor(world: World, a: WallAuthority, author: WallAuthor): boolean {
  const n = author.note,
    data = readWallNoteData(n),
    source = Object.getOwnPropertyDescriptor(n, "source");
  const writable = ["remaining", "expired"].every((key) => {
    const field = Object.getOwnPropertyDescriptor(n, key);
    return field && Object.hasOwn(field, "value") && field.writable === true;
  });
  return (
    writable &&
    !!data &&
    active.get(world) === a &&
    a.isCurrent() &&
    sameDebateParticipant(world, author.participant) &&
    world.getComponent(author.id, COMPONENT.WallNote) === n &&
    source?.value === author.source &&
    data.instanceId === author.instanceId &&
    data.remaining === author.remaining &&
    data.expired === false
  );
}

export function authorizedWallAuthor(
  world: World,
  id: number,
  token: string | undefined,
  instanceId: string | undefined,
  scope: object | undefined,
): WallAuthor | null {
  const a = active.get(world),
    author = a?.authors.get(id);
  return a &&
    a === scope &&
    author &&
    a.token === token &&
    author.instanceId === instanceId &&
    author.remaining === 1 &&
    sameWallAuthor(world, a, author)
    ? author
    : null;
}
export function closeWall(world: World, a: WallAuthority): void {
  if (active.get(world) !== a) return;
  active.delete(world);
  for (const author of a.authors.values()) {
    author.closed = true;
    const field = Object.getOwnPropertyDescriptor(author.note, "expired");
    if (field && Object.hasOwn(field, "value") && field.writable)
      try {
        Object.defineProperty(author.note, "expired", { ...field, value: true });
      } catch {
        /* Runtime revocation is independent of a corrupted storage object. */
      }
  }
}
export function projectWallNote(
  world: World,
  id: number,
): (WallNoteComponent & { effectiveRemaining: 0 | 1 }) | undefined {
  const a = active.get(world),
    author = a?.authors.get(id);
  const n = world.getComponent(id, COMPONENT.WallNote);
  const owner = owned.get(world)?.get(id);
  if (!owner || owner.note !== n) return;
  const data = readWallNoteData(n),
    source = n && Object.getOwnPropertyDescriptor(n, "source");
  if (
    !data ||
    source?.value !== owner.source ||
    data.instanceId !== owner.instanceId ||
    data.remaining !== owner.remaining
  )
    return;
  return {
    ...data,
    expired: owned.get(world)!.get(id)!.closed || data.expired,
    effectiveRemaining: a && author && sameWallAuthor(world, a, author) ? author.remaining : 0,
  };
}

/**
 * 开启已配置的匿名墙机会并收集原作者行动。输入为只读政策、World、Provider 及具名 RNG 工厂；输出为墙事实与窗口完成，库存和请求关闭归 authority，不改规则或取得其他能力。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import {
  COMPONENT,
  Phase,
  type World,
  type ActionProvider,
  type GameEvent,
  type ToolCall,
} from "../../../../core/domain";
import { shuffled, type RandomSource } from "../../../../core/domain/random";
import { readWallTool } from "@ai-werewolf-arena/game-contract/facts/wall-notes";
import type { ActionRequestConstructionPort } from "../../../../core/domain/actions";
import { ToolGateway } from "../../../gateway/tool_gateway";
import {
  openWall,
  closeWall,
  grantWallNote,
  sameWallAuthor,
  hasActiveWall,
  hasWallCommit,
  type WallAuthor,
} from "./authority";
export class WallNotesWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    requests: ActionRequestConstructionPort,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
    random: () => RandomSource,
  ): Promise<void> {
    if (hasActiveWall(this.world)) throw new Error("wall_window_reentry");
    if (
      config.events?.pack !== "awa_wall_notes_once_v1" ||
      day !== 1 ||
      hasWallCommit(this.world) ||
      !isCurrent()
    )
      return;
    const pack = config.events;
    const windowCurrent = () =>
      isCurrent() && config.events === pack && pack.pack === "awa_wall_notes_once_v1";
    const a = openWall(this.world, windowCurrent);
    const cancel = () => {
      if (isCurrent())
        this.events.push({
          timestamp: Date.now(),
          type: "wall_notes_canceled",
          payload: { day: 1, eventId: "awa_wall_notes_v1", reason: "scope_changed" },
        });
    };
    const change = (
      author: WallAuthor,
      operation: "granted" | "accepted" | "rejected" | "revoked" | "expired",
      text?: string,
    ) =>
      this.events.push({
        timestamp: Date.now(),
        type: "wall_note_changed",
        payload: {
          actorId: author.id,
          day: 1,
          eventId: "awa_wall_notes_v1",
          itemId: "anonymous_note",
          instanceId: author.instanceId,
          operation,
          remaining: author.remaining,
          expired: operation === "expired",
          ...(operation === "accepted" ? { text: text! } : {}),
        },
      });
    const base = { day: 1 as const, eventId: "awa_wall_notes_v1" as const };
    try {
      this.events.push({ timestamp: Date.now(), type: "wall_notes_started", payload: base });
      const authors = this.world
        .getAliveEntityIds()
        .sort((x, y) => x - y)
        .flatMap((id) => {
          const author = grantWallNote(this.world, a, id);
          if (!author) return [];
          change(author, "granted");
          return [author];
        });
      const calls = authors.map((author) => ({
        author,
        request: requests.create({
          actorId: author.id,
          phase: Phase.Voting,
          allowedTools: ["write_note"],
          stage: "wall_notes",
          requiresAction: false,
          summary: { key: "request.summary.wall_notes" },
          context: { wall_id: a.token, item_instance_id: author.instanceId, allow_fallback: false },
        }),
      }));
      const results = await Promise.allSettled(
        calls.map(({ author, request }) =>
          sameWallAuthor(this.world, a, author)
            ? Promise.resolve().then(() =>
                sameWallAuthor(this.world, a, author) ? provider.getAction(request) : null,
              )
            : Promise.resolve(null),
        ),
      );
      const failure = results.find((result) => result.status === "rejected");
      if (failure?.status === "rejected") throw failure.reason;
      if (!windowCurrent()) {
        cancel();
        return;
      }
      const accepted: Array<{ author: WallAuthor; text: string }> = [];
      for (let i = 0; i < calls.length; i++) {
        const { author } = calls[i],
          result = results[i];
        if (!sameWallAuthor(this.world, a, author)) {
          change(author, "revoked");
          continue;
        }
        const call = result.status === "fulfilled" ? readWallTool(result.value) : null;
        if (!call) {
          if (result.status === "fulfilled" && result.value !== null) change(author, "rejected");
          continue;
        }
        const valid = this.gateway.validateAndSanitize(this.world, author.id, call, {
          phase: Phase.Voting,
          day: 1,
          wallScope: a,
          wallId: a.token,
          itemInstanceId: author.instanceId,
        });
        if (!sameWallAuthor(this.world, a, author)) {
          change(author, "revoked");
          continue;
        }
        if (!valid.ok) {
          change(author, "rejected");
          continue;
        }
        author.remaining = 0;
        author.note.remaining = 0;
        change(author, "accepted", call.args.text);
        accepted.push({ author, text: call.args.text });
      }
      if (!windowCurrent()) {
        cancel();
        return;
      }
      const current = accepted.filter((row) => {
        if (sameWallAuthor(this.world, a, row.author)) return true;
        change(row.author, "revoked");
        return false;
      });
      const ordered = current.sort((x, y) =>
        x.text < y.text ? -1 : x.text > y.text ? 1 : x.author.id - y.author.id,
      );
      const final = shuffled(ordered, random());
      if (!windowCurrent() || final.some((row) => !sameWallAuthor(this.world, a, row.author))) {
        cancel();
        return;
      }
      this.events.push(
        {
          timestamp: Date.now(),
          type: "wall_note_order_recorded",
          payload: {
            ...base,
            rows: final.map(({ author, text }, rank) => ({
              actorId: author.id,
              instanceId: author.instanceId,
              text,
              rank,
            })),
          },
        },
        {
          timestamp: Date.now(),
          type: "wall_notes_published",
          payload: { ...base, texts: final.map((row) => row.text) },
        },
      );
    } finally {
      closeWall(this.world, a);
      for (const author of a.authors.values()) change(author, "expired");
    }
  }
}

/**
